  1	/* ============================================================
  2	   views/config.js — Configuration view
  3	   Section 4d of the MCP Server Dashboard SPA
  4	   Depends on: API, escapeHtml, showLoading, showError
  5	   ============================================================ */
  6	
  7	/* ── Module-level state ──────────────────────────────────── */
  8	
  9	var configActiveTab = 'general';
 10	
 11	/* Dirty-tracking: keyed by tab name, true when the tab has unsaved changes */
 12	var configDirty = {
 13	  general: false,
 14	  personaModels: false,
 15	  modelRegistry: false
 16	};
 17	
 18	/* ── Entry point ─────────────────────────────────────────── */
 19	
 20	function renderConfig(app) {
 21	  showLoading(app);
 22	
 23	  Promise.all([
 24	    API.getConfig(),
 25	    API.getModels ? API.getModels() : Promise.resolve([]),
 26	    API.getPersonas ? API.getPersonas() : Promise.resolve([]),
 27	    API.getAssignments ? API.getAssignments() : Promise.resolve([])
 28	  ]).then(function (results) {
 29	    var config      = results[0];
 30	    var models      = results[1];
 31	    var personas    = results[2];
 32	    var assignments = results[3];
 33	
 34	    renderConfigPage(app, config, models, personas, assignments);
 35	  }).catch(function (err) {
 36	    showError(app, 'Failed to load configuration: ' + (err.message || String(err)));
 37	  });
 38	}
 39	
 40	/* ── Page scaffold ───────────────────────────────────────── */
 41	
 42	function renderConfigPage(app, config, models, personas, assignments) {
 43	  app.innerHTML =
 44	    '<div class="page-header"><h1>Configuration</h1></div>' +
 45	    '<div class="config-tabs" id="config-tab-bar">' +
 46	      '<button class="config-tab' + (configActiveTab === 'general'       ? ' active' : '') + '" data-tab="general">General</button>' +
 47	      '<button class="config-tab' + (configActiveTab === 'personaModels' ? ' active' : '') + '" data-tab="personaModels">Persona Models</button>' +
 48	      '<button class="config-tab' + (configActiveTab === 'modelRegistry' ? ' active' : '') + '" data-tab="modelRegistry">Model Registry</button>' +
 49	    '</div>' +
 50	    '<div id="config-tab-content"></div>';
 51	
 52	  /* Render active tab content */
 53	  renderConfigTabContent(config, models, personas, assignments);
 54	
 55	  /* Wire tab-bar clicks */
 56	  var tabBar = document.getElementById('config-tab-bar');
 57	  if (tabBar) {
 58	    tabBar.addEventListener('click', function (e) {
 59	      var btn = e.target.closest('button[data-tab]');
 60	      if (!btn) return;
 61	      var tab = btn.getAttribute('data-tab');
 62	      if (tab === configActiveTab) return;
 63	
 64	      /* Unsaved-changes guard */
 65	      if (configDirty[configActiveTab]) {
 66	        if (!confirm('You have unsaved changes. Discard them?')) {
 67	          return; /* Stay */
 68	        }
 69	        configDirty[configActiveTab] = false;
 70	      }
 71	
 72	      /* Update active tab state */
 73	      configActiveTab = tab;
 74	
 75	      /* Update active class on buttons without re-rendering the full page */
 76	      var allBtns = tabBar.querySelectorAll('.config-tab');
 77	      allBtns.forEach(function (b) {
 78	        b.classList.toggle('active', b.getAttribute('data-tab') === tab);
 79	      });
 80	
 81	      /* Re-render only the tab content area */
 82	      renderConfigTabContent(config, models, personas, assignments);
 83	    });
 84	  }
 85	}
 86	
 87	/* ── Tab content dispatcher ──────────────────────────────── */
 88	
 89	function renderConfigTabContent(config, models, personas, assignments) {
 90	  var contentEl = document.getElementById('config-tab-content');
 91	  if (!contentEl) return;
 92	
 93	  if (configActiveTab === 'general') {
 94	    contentEl.innerHTML = renderGeneralTab(config);
 95	    wireGeneralTabEvents();
 96	  } else if (configActiveTab === 'personaModels') {
 97	    contentEl.innerHTML = renderPersonaModelsTab(models, personas, assignments);
 98	  } else if (configActiveTab === 'modelRegistry') {
 99	    contentEl.innerHTML = renderModelRegistryTab(models);
100	  }

101	}
102	
103	/* ── General tab ─────────────────────────────────────────── */
104	
105	function renderGeneralTab(config) {
106	  return UI.card(null,
107	    '<form id="config-form">' +
108	      '<div class="form-group">' +
109	        '<label class="form-label" for="auto-handoff">' +
110	          '<input type="checkbox" id="auto-handoff" class="form-check" ' + (config.auto_handoff_enabled ? 'checked' : '') + '>' +
111	          ' Auto-handoff enabled' +
112	        '</label>' +
113	        '<p class="form-note">When enabled, the MCP server automatically chains work to the next agent in the workflow.</p>' +
114	      '</div>' +
115	      '<div class="form-group">' +
116	        '<label class="form-label" for="max-depth">Max handoff depth</label>' +
117	        '<input type="number" id="max-depth" class="form-control" min="1" value="' + escapeHtml(String(config.max_handoff_depth)) + '">' +
118	        '<p class="form-note">Maximum number of automatic agent handoffs before stopping.</p>' +
119	      '</div>' +
120	      '<div class="form-group">' +
121	        '<label class="form-label" for="capture-dialogues">' +
122	          '<input type="checkbox" id="capture-dialogues" class="form-check" ' + (config.capture_dialogues ? 'checked' : '') + '>' +
123	          ' Capture agent dialogues' +
124	        '</label>' +
125	        '<p class="form-note">When enabled, the orchestrator saves the full LLM conversation for each pipeline stage to the project\'s ledger as Markdown files. Changes take effect on the next orchestrator run.</p>' +
126	      '</div>' +
127	      '<div class="form-group">' +
128	        '<label class="form-label" for="auto-archive-days">Auto-archive after (days)</label>' +
129	        '<input type="number" id="auto-archive-days" class="form-control" min="0" step="1" value="' + escapeHtml(String(config.auto_archive_days != null ? config.auto_archive_days : 6)) + '">' +
130	        '<p class="form-note">Number of days after last update before a COMPLETE project is automatically archived. Set to 0 to disable auto-archiving.</p>' +
131	      '</div>' +
132	      '<div class="form-group">' +
133	        '<label class="form-label" for="ledger-root">Ledger root path</label>' +
134	        '<input type="text" id="ledger-root" class="form-control" readonly value="' + escapeHtml(config.ledger_root || '') + '">' +
135	        '<p class="form-note">Read-only. Changing this requires restarting the server with <code>--ledger-dir</code>.</p>' +
136	      '</div>' +
137	      '<button type="submit" class="btn btn-primary">Save</button>' +
138	      '<div id="config-msg"></div>' +
139	    '</form>',
140	    { style: 'max-width:560px' }
141	  );
142	}
143	
144	function wireGeneralTabEvents() {
145	  var form = document.getElementById('config-form');
146	  if (!form) return;
147	
148	  /* Mark tab dirty on any input change */
149	  form.addEventListener('change', function () {
150	    configDirty.general = true;
151	  });
152	  form.addEventListener('input', function () {
153	    configDirty.general = true;
154	  });
155	
156	  form.addEventListener('submit', function (e) {
157	    e.preventDefault();
158	    var autoHandoff = document.getElementById('auto-handoff').checked;
159	    var maxDepth = parseInt(document.getElementById('max-depth').value, 10);
160	    if (isNaN(maxDepth) || maxDepth < 1) {
161	      showError(document.getElementById('config-msg'), 'Max handoff depth must be a positive integer.');
162	      return;
163	    }
164	    var captureDialogues = document.getElementById('capture-dialogues').checked;
165	    var autoArchiveDays = parseInt(document.getElementById('auto-archive-days').value, 10);
166	    if (isNaN(autoArchiveDays) || autoArchiveDays < 0) {
167	      showError(document.getElementById('config-msg'), 'Auto-archive days must be a non-negative integer.');
168	      return;
169	    }
170	    /* ledger_root intentionally omitted (read-only) */
171	    API.updateConfig({ auto_handoff_enabled: autoHandoff, max_handoff_depth: maxDepth, capture_dialogues: captureDialogues, auto_archive_days: autoArchiveDays })
172	      .then(function () {
173	        configDirty.general = false;
174	        document.getElementById('config-msg').innerHTML = '<p class="success-banner">Configuration saved.</p>';
175	      })
176	      .catch(function (err) {
177	        showError(document.getElementById('config-msg'), 'Save failed: ' + (err.message || String(err)));
178	      });
179	  });
180	}
181	
182	/* ── Persona Models tab (stub) ───────────────────────────── */
183	
184	function renderPersonaModelsTab(models, personas, assignments) {
185	  return UI.card(null,
186	    '<div class="empty-state">' +
187	      '<p class="empty-state-text">Persona Models — Coming soon</p>' +
